type Server struct {
    addr    string
    timeout time.Duration
    logger  Logger
}

type Option func(*Server)

func WithTimeout(timeout time.Duration) Option {
    return func(s *Server) {
        s.timeout = timeout
    }
}

func WithLogger(logger Logger) Option {
    return func(s *Server) {
        s.logger = logger
    }
}

func NewServer(addr string, opts ...Option) *Server {
    s := &Server{
        addr:    addr,
        timeout: 30 * time.Second,
    }
    for _, opt := range opts {
        opt(s)
    }
    return s
}

// Usage
server := NewServer(":8080",
    WithTimeout(60*time.Second),
    WithLogger(myLogger),
)

// Repository interface
type UserRepository interface {
    GetByID(ctx context.Context, id string) (*User, error)
    Create(ctx context.Context, user *User) error
    Update(ctx context.Context, user *User) error
    Delete(ctx context.Context, id string) error
}

// Implementation
type SQLUserRepository struct {
    db *sql.DB
}

func (r *SQLUserRepository) GetByID(ctx context.Context, id string) (*User, error) {
    // SQL implementation
}

// Service uses the interface
type UserService struct {
    repo UserRepository
}

func (s *UserService) GetUser(ctx context.Context, id string) (*User, error) {
    return s.repo.GetByID(ctx, id)
}

import (
    "errors"
    "fmt"
)

var ErrNotFound = errors.New("not found")

func LoadUser(id string) (*User, error) {
    user, err := db.Query(id)
    if err != nil {
        return nil, fmt.Errorf("failed to query user %s: %w", id, err)
    }
    if user == nil {
        return nil, fmt.Errorf("user %s: %w", id, ErrNotFound)
    }
    return user, nil
}

// Checking errors
if err := LoadUser("123"); err != nil {
    if errors.Is(err, ErrNotFound) {
        // handle not found
    }
    return err
}

var (
    ErrUserNotFound    = errors.New("user not found")
    ErrInvalidCredentials = errors.New("invalid credentials")
    ErrRateLimitExceeded  = errors.New("rate limit exceeded")
)

func Authenticate(username, password string) error {
    user, err := repo.FindByUsername(username)
    if err != nil {
        return fmt.Errorf("failed to find user: %w", err)
    }
    if user == nil {
        return ErrUserNotFound
    }
    if !user.CheckPassword(password) {
        return ErrInvalidCredentials
    }
    return nil
}

type Job struct {
    ID   string
    Data []byte
}

type Result struct {
    JobID string
    Err   error
}

func worker(ctx context.Context, id int, jobs <-chan Job, results chan<- Result) {
    for job := range jobs {
        select {
        case <-ctx.Done():
            return
        default:
            err := processJob(job)
            results <- Result{JobID: job.ID, Err: err}
        }
    }
}

func StartWorkers(ctx context.Context, numWorkers int, jobs []Job) []Result {
    jobChan := make(chan Job, len(jobs))
    resultChan := make(chan Result, len(jobs))

    // Start workers
    var wg sync.WaitGroup
    for i := 0; i < numWorkers; i++ {
        wg.Add(1)
        go func(id int) {
            defer wg.Done()
            worker(ctx, id, jobChan, resultChan)
        }(i)
    }

    // Send jobs
    for _, job := range jobs {
        jobChan <- job
    }
    close(jobChan)

    // Wait for completion
    go func() {
        wg.Wait()
        close(resultChan)
    }()

    // Collect results
    var results []Result
    for result := range resultChan {
        results = append(results, result)
    }
    return results
}

func (s *Service) ProcessData(ctx context.Context, input string) (string, error) {
    // Add timeout
    ctx, cancel := context.WithTimeout(ctx, 5*time.Second)
    defer cancel()

    // Pass context to dependencies
    data, err := s.repo.Fetch(ctx, input)
    if err != nil {
        return "", fmt.Errorf("fetch failed: %w", err)
    }

    // Check for cancellation
    select {
    case <-ctx.Done():
        return "", ctx.Err()
    default:
    }

    result, err := s.process(ctx, data)
    if err != nil {
        return "", fmt.Errorf("process failed: %w", err)
    }

    return result, nil
}

func processParallel(ctx context.Context, items []Item) ([]Result, error) {
    // Fan out: start a goroutine for each item
    resultChan := make(chan Result, len(items))
    var wg sync.WaitGroup

    for _, item := range items {
        wg.Add(1)
        go func(item Item) {
            defer wg.Done()
            result := processItem(ctx, item)
            resultChan <- result
        }(item)
    }

    // Wait for all goroutines to finish
    go func() {
        wg.Wait()
        close(resultChan)
    }()

    // Fan in: collect all results
    var results []Result
    for result := range resultChan {
        results = append(results, result)
    }

    return results, nil
}

func TestAdd(t *testing.T) {
    tests := []struct {
        name     string
        a, b     int
        expected int
    }{
        {"positive numbers", 2, 3, 5},
        {"negative numbers", -2, -3, -5},
        {"mixed", -2, 3, 1},
        {"zero", 0, 0, 0},
    }

    for _, tt := range tests {
        t.Run(tt.name, func(t *testing.T) {
            result := Add(tt.a, tt.b)
            if result != tt.expected {
                t.Errorf("Add(%d, %d) = %d, want %d",
                    tt.a, tt.b, result, tt.expected)
            }
        })
    }
}

// testhelpers.go
func setupTestDB(t *testing.T) *sql.DB {
    db, err := sql.Open("sqlite3", ":memory:")
    if err != nil {
        t.Fatalf("failed to open test db: %v", err)
    }
    // Run migrations
    if err := runMigrations(db); err != nil {
        t.Fatalf("failed to run migrations: %v", err)
    }
    return db
}

func cleanupTestDB(t *testing.T, db *sql.DB) {
    if err := db.Close(); err != nil {
        t.Logf("failed to close db: %v", err)
    }
}

